css:
body{margin:0;background:#FCF9F6;color:#160A0F;font-family:'Hanken Grotesk',system-ui,sans-serif;-webkit-font-smoothing:antialiased}
a{color:#160A0F}a:hover{color:#800039}
*{box-sizing:border-box}
@keyframes subir{from{opacity:0;transform:translateY(26px)}to{opacity:1;transform:none}}
@keyframes respirar{0%,100%{transform:scale(1)}50%{transform:scale(1.1)}}
.l1{animation:subir .8s .2s cubic-bezier(.2,.7,.1,1) both}
.l2{animation:subir .8s .35s cubic-bezier(.2,.7,.1,1) both}
.luz{animation:respirar 8s ease-in-out infinite}
.hablamos{position:relative;isolation:isolate;display:inline-flex;align-items:center;justify-content:center;min-height:64px;padding:0 34px;font-weight:700;font-size:17px;letter-spacing:.16em;text-transform:uppercase;text-decoration:none;color:#160A0F}
.hablamos:hover{color:#160A0F}
.hablamos .txt{position:relative;z-index:1;transition:transform .3s cubic-bezier(.2,.7,.1,1)}
.hablamos .punto{position:absolute;left:calc(100% - 44px);top:50%;width:64px;height:64px;margin:-32px 0 0 -32px;border-radius:50%;z-index:0;background:radial-gradient(circle at 38% 35%,#FF8A65 0%,#F45430 50%,#E0423E 100%);filter:blur(5px);transition:transform .4s cubic-bezier(.2,.7,.1,1),filter .4s ease}
.hablamos:hover .punto{filter:blur(7px)}
button.hablamos{border:0;background:transparent;font-family:inherit;cursor:pointer}
.hablamos.claro,.hablamos.claro:hover{color:#FCF9F6}
.faq details{border-top:1px solid #E6DAD3}
.faq details:last-of-type{border-bottom:1px solid #E6DAD3}
.faq summary{list-style:none;display:flex;justify-content:space-between;align-items:center;gap:24px;padding:24px 0;font-size:19px;font-weight:700;line-height:1.35;color:#160A0F;cursor:pointer}
.faq summary::-webkit-details-marker{display:none}
.faq .ar{flex:none;font-size:20px;transition:transform .3s ease}
.faq details[open] .ar{transform:rotate(-90deg)}
.faq details p{margin:0 0 24px;max-width:600px;font-size:17px;line-height:1.65;color:#3D2C34}
.campo{display:flex;flex-direction:column;gap:8px}
.campo span{font-size:14px;font-weight:600;letter-spacing:.02em;color:#6B0A33}
.campo input,.campo textarea{width:100%;border:0;border-bottom:1px solid #CDBFB8;background:transparent;padding:8px 0 12px;font:inherit;font-size:18px;color:#160A0F;outline:none;resize:none;border-radius:0;transition:border-color .25s ease}
.campo input::placeholder,.campo textarea::placeholder{color:#8F7C84}
.campo input:focus,.campo textarea:focus{border-bottom-color:#160A0F}
.legal{color:#FFFFFF;text-decoration:none}.legal:hover{color:#FFFFFF;text-decoration:underline;text-underline-offset:4px}
.check{display:flex;align-items:flex-start;gap:12px;font-size:14px;line-height:1.5;color:#3D2C34;cursor:pointer}
.check input{flex:none;width:18px;height:18px;margin:1px 0 0;accent-color:#800039;cursor:pointer}
.check a{color:#3D2C34;text-underline-offset:3px}
.etq{margin:26px 0 6px;font-size:13px;font-weight:700;letter-spacing:.16em;text-transform:uppercase;color:#6B0A33}
.portada{position:relative;overflow:hidden;background:#800039;aspect-ratio:4/3}
.portada .mancha{position:absolute;inset:-10%;filter:blur(40px)}
.portada img{position:absolute;right:22px;bottom:22px;width:40px;height:auto}
.portada .preg{position:absolute;left:24px;top:22px;right:24px;font-size:13px;font-weight:700;letter-spacing:.14em;text-transform:uppercase;color:#FCF9F6}
.tarjeta{display:flex;flex-direction:column;gap:18px;text-decoration:none;color:#160A0F}
.tarjeta:hover{color:#160A0F}
.tarjeta:hover h3{text-decoration:underline;text-underline-offset:5px;text-decoration-thickness:1px}
.art p{margin:0 0 22px;font-size:19px;line-height:1.75;color:#2E2028}
.art h2{margin:56px 0 18px;font-family:'Hanken Grotesk',system-ui,sans-serif;font-weight:800;font-size:34px;line-height:1.15;letter-spacing:-.015em;color:#160A0F;scroll-margin-top:110px}
.art ul{margin:0 0 26px;padding:0;list-style:none}
.art li{position:relative;padding:12px 0 12px 26px;border-top:1px solid #E6DAD3;font-size:18px;line-height:1.6;color:#2E2028}
.art li:last-child{border-bottom:1px solid #E6DAD3}
.art li::before{content:"";position:absolute;left:0;top:22px;width:9px;height:9px;border-radius:50%;background:#F45430}
.art a{color:#800039;text-underline-offset:4px}
.tabla{overflow-x:auto;margin:0 0 28px}
.art table{width:100%;min-width:600px;border-collapse:collapse;font-size:16px;line-height:1.5;color:#2E2028}
.art th,.art td{text-align:left;vertical-align:top;padding:14px 14px 14px 0;border-top:1px solid #E6DAD3}
.art tr:last-child td{border-bottom:1px solid #E6DAD3}
.art th{font-size:13px;font-weight:700;letter-spacing:.12em;text-transform:uppercase;color:#6B0A33}
.art td:first-child{font-weight:700;color:#160A0F}
.cuenta{margin:8px 0 28px;padding:32px;background:#F3ECFF;display:flex;flex-direction:column;gap:10px}
.cuenta p{margin:0 !important}
.cuenta .grande{font-size:26px !important;font-weight:800;line-height:1.3 !important;color:#160A0F !important}
.indice a{display:block;padding:9px 0 9px 16px;border-left:1px solid #E6DAD3;font-size:15px;line-height:1.4;color:#6E5A63;text-decoration:none}
.indice a.on{border-left:2px solid #F45430;color:#160A0F;font-weight:700}
@media (prefers-reduced-motion:reduce){.l1,.l2,.luz{animation:none}.hablamos .punto,.hablamos .txt{transition:none}}
@media (max-width:860px){.cuerpo{grid-template-columns:1fr !important;gap:40px !important}.cuerpo aside{position:static !important}.rel{grid-template-columns:1fr !important}.hab{grid-template-columns:1fr !important;gap:56px !important}.cab{grid-template-columns:auto 1fr !important}.cab nav{display:none !important}}
